INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xcavator 2025', 'This is Xcavator 2025 (NES Cartridge), a fully functional NES title built from Oberth’s original design of the same name. First developed at Incredible Technologies Inc., the company behind coin-op classics like Golden Tee Golf, Big Buck Hunter, and more, Xcavator was shopped around to multiple publishers across the country way back in 1991, but it never found a home, and was quietly archived and never looked at again.' FROM games WHERE igdb_id = 381088 ON CONFLICT (game_id, language_code) DO NOTHING;
