INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nightsoil', 'Nightsoil is a story-driven walking simulator. Set in cholera-ravaged 1854 London, the game follows an aging gong farmer on his final shift. As he works through the nightly routine of shoveling human waste, memories of a life shaped by loss, hardship, and the enduring bond with his horse, Ol’ Boy, rise to the surface.' FROM games WHERE igdb_id = 391672 ON CONFLICT (game_id, language_code) DO NOTHING;
