INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Vig', 'You''ll be "Xie En", infiltrating the traitor''s money empire. This urban hunt is a revenge saga where wit is your spear. Return as "Wu Wei," using rules as your shield in a world of grey. Will you choose love or vengeance? This lethal game of cash, betrayal and redemption awaits your move.' FROM games WHERE igdb_id = 390351 ON CONFLICT (game_id, language_code) DO NOTHING;
