INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deco Online Origins', 'Deco Online Origins is a free-to-play 3D MMORPG that put players deep into the fantastic story of two warring nations, "Millena" and "Rain". As a legendary swordsman, a fierce archer, or a master of wizardry, players were constantly challenged by the opposing nation and by monsters that lurked around every corner. Notable features included a combo system with hundreds of potential skills, and guardian pets that buffed entire guilds.' FROM games WHERE igdb_id = 384363 ON CONFLICT (game_id, language_code) DO NOTHING;
