INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pixicharm: BitPew', 'BitPew is a fast-paced retro arcade shooter inspired by classic handheld action. Take control of a robot head equipped with a vertical turret and put your memory and reflexes to the test. A faded silhouette of one of five enemy types slowly descends from the top of the screen. Watch carefully, identify the shape, and shoot the matching enemy before it reaches the bottom. Every mistake costs a life, and once they’re gone, it’s game over. With simple controls, chunky pixel graphics, and intense score-chasing gameplay, BitPew delivers a focused arcade experience where every shot matters.' FROM games WHERE igdb_id = 392346 ON CONFLICT (game_id, language_code) DO NOTHING;
