INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pixicharm: Acornflare', 'Dash through a magical forest in this fast-paced endless runner where every decision matters. Play as a nimble squirrel collecting acorns to boost your score, then transform into a fiery imp to defeat incoming enemies. Switch forms at the perfect moment, keep your momentum alive, and push your run as far as you can! Vultures, bats, and owls swoop in from above—some you dodge as a squirrel, others you burn away as a fire imp. Balancing both forms becomes the key to surviving longer and reaching higher scores.' FROM games WHERE igdb_id = 389416 ON CONFLICT (game_id, language_code) DO NOTHING;
