INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Twenty One', 'You wake up in a velvet-draped casino that seems suspended in a void, run by faceless dealers and watched by an unseen Host. You''re told you owe a "debt of existence" and must earn your right to live another day by beating the Quota — a cash target that rises with each round. You have 5 rounds to meet or exceed the quota, or… you''re out. Permanently.' FROM games WHERE igdb_id = 395559 ON CONFLICT (game_id, language_code) DO NOTHING;
