INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yāo Liàn Xī Yóu', 'You, an ordinary college student, are unexpectedly reincarnated into another world, becoming the new "Golden Body" chosen by Jin Chanzi. Characters from "Journey to the West" suddenly reappear before you in the guise of women. To return to your original world, you must complete the mission entrusted to you by "Tathagata Buddha." Renew your bonds with various demons, undo the mistakes of the previous Golden Body, "Tang Sanzang," and retrace your journey westward, reshaping order and causality...' FROM games WHERE igdb_id = 373711 ON CONFLICT (game_id, language_code) DO NOTHING;
