INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FNaF 2: Night of Misfits', '"FNaF 2 Night of Misfits" is a fan game created as an unofficial project based on Scott Cawthon''s Five Nights at Freddy''s. It is a non-commercial creative incarnation developed from scratch and differs from the original in both mechanics and story. It is important to note that "FNaF 2 Night of Misfits" is not an official or free version of "Five Nights at Freddy''s" and is not to be distributed for money' FROM games WHERE igdb_id = 280135 ON CONFLICT (game_id, language_code) DO NOTHING;
