INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Odd One Out 2', 'Odd One Out 2 is a simple, fun word puzzle game with 12 different subjects that can be selected on the rounds screen (for example Sport & Leisure). Each subject has 10 puzzles and each puzzle is a different category within the overall theme – for instance Water Sports or Famous Racehorses. For each category there are 12 answers on the screen but one does not belong in the category and is the odd one out. Simply find the answer in each category that does not belong. There is no time limit and each subject can be played as many times as you need to reach a great score!' FROM games WHERE igdb_id = 390895 ON CONFLICT (game_id, language_code) DO NOTHING;
