INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thumbylina', 'Thumbylina is a fingertip-sized life simulation game device designed to be your daily companion. When you set a timer during study or exercise, your in-game character joins you in self-improvement—unlocking new outfits and hairstyles as you progress. Unlike smartphone or PC timer apps, Thumbylina is completely offline, allowing you to focus without any distracting notifications.' FROM games WHERE igdb_id = 354135 ON CONFLICT (game_id, language_code) DO NOTHING;
