INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kaz', 'KAZ, your shot of dopamine wrapped in a minimalist roguelike. Execute lightning-fast moves with frame-perfect controls : easy to learn, hard to master. Immediate, Intense, Addictive. Every run makes you better, faster, hungrier, unlocking tons of unique items, skins and challenges.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 343586 AND ge.slug = 'indie' ON CONFLICT DO NOTHING;
