INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sandwich Simulator', 'Sandwich Simulator is a restaurant simulation game that can be played solo or with up to 4 players in online co-op. Players manage a sandwich shop by taking orders, preparing sandwiches and side items, cleaning the restaurant, and ensuring customer satisfaction. Time management, task coordination, kitchen layout, and restaurant expansion are key elements of the gameplay. The game offers both single-player and cooperative multiplayer.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 345351 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
