INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Omi Oh My AI', 'Go on a captchavating adventure with Omi, a friendly (if a bit quirky) artificial intelligence! Learn to see the world the way Omi does as you solve image, word, and number puzzles inspired by the CAPTCHAs we’ve all had to do to prove we’re not a robot. Go outside the game and explore websites chronicling Omi’s development and learn how to solve the game’s stranger puzzles in this game inspired by AI, I Love Bees, the 90’s, and the constant need to prove you’re not a robot.' FROM games WHERE igdb_id = 215393 ON CONFLICT (game_id, language_code) DO NOTHING;
