INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'isekizima: Ruins and Tails Journey', 'This is an action game where you explore ruins buried in the forest with Ethnic BGM. Kijino, a cat-eared adventurer with two tails (Nekomata), goes on a journey around the ISEKIZIMA (Ruins Island of dreams and romance : as it was written in the tourist brochure).' FROM games WHERE igdb_id = 285950 ON CONFLICT (game_id, language_code) DO NOTHING;
