INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panic of the Apes', 'Panic of the Apes is a chaotic 1 to 4 player couch PvP game where apes battle to stockpile before a volcano erupts. Grab bananas, pelt rivals to steal theirs, eat for speed boosts, loot chests, and dodge roll to deflect shots. Most bananas at zero wins. First ape to three rounds is King Chimp!' FROM games WHERE igdb_id = 394290 ON CONFLICT (game_id, language_code) DO NOTHING;
