INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Untamed Isle', 'Untamed Isle is a laid-back treasure hunt with two bite-size levels built for pure relaxation. Wander through a lush jungle paradise, follow your curiosity, and scoop up glowing treasures hidden across the island—no tools, no combat, no stress. Just smooth exploration, bright vibes, and a cute cast to keep you company as you aim for a perfect clear.' FROM games WHERE igdb_id = 395197 ON CONFLICT (game_id, language_code) DO NOTHING;
