INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nodosis', 391466, '2026-03-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobl3l.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5ed0.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nodosis', 'Nodosis is a tic-tac-toe-inspired rogue-like deckbuilder where you play an endless game of high-scores, tile synergies and mysteriously accursed rings. Score, Retrigger, Multiply, Modify, Win and Lose. It''s up to you how you want to play this game, Nodosis. Willing to take the chance?' FROM games WHERE igdb_id = 391466 ON CONFLICT (game_id, language_code) DO NOTHING;
