INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neon Vault Rush', 'Neon Vault Rush is a high-speed 3D parkour game set in a glowing cyberpunk world. Dash through dizzying circuits filled with deadly traps, floating platforms, and pulse-pounding synthwave beats. Master wall runs, double jumps, and acrobatic moves as you race against time and chase your best records. One wrong step — game over. If you crave speed, precision, and the thrill of a digital dreamscape, this is your playground.' FROM games WHERE igdb_id = 394634 ON CONFLICT (game_id, language_code) DO NOTHING;
