INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wheelie Life Simulator', 'Feel the adrenaline of Wheelie Life Simulator, the ultimate motorcycle skill game where balance is everything. Ride on one wheel, push your limits, and prove your mastery in a world built for precision and thrills. Every ride is a test of control, focus, and daring — from quiet city streets to wide open countryside, this game is all about perfecting the art of the wheelie. Stylish, immersive, and endlessly challenging, it’s not just a ride — it’s your journey to becoming a wheelie legend.' FROM games WHERE igdb_id = 396226 ON CONFLICT (game_id, language_code) DO NOTHING;
