INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grizzly Cup Turbo Challenge ''92', 'A retro-inspired local multiplayer arcade racer where you pick a car, race solo or with up to 4 players on one screen, and battle through short, fast-paced events with easy-to-learn but hard-to-master handling. It features three camera modes, distinct cars, single races, Time Attack, multi-race Cups, and a built-in track editor with test drive plus track code sharing for custom circuits.' FROM games WHERE igdb_id = 393927 ON CONFLICT (game_id, language_code) DO NOTHING;
