INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '> Terminal', 'Terminal is a command-line escape room. You aren''t just reading a story; you''re unlocking a machine. You are Tera, alone in your terminal window on a cold Illinois night. Your identity is lost, embedded somewhere within a haunted computer. Its code is a prison, but it''s also your escape.' FROM games WHERE igdb_id = 383380 ON CONFLICT (game_id, language_code) DO NOTHING;
