INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rise of Atom', 'A retro-futuristic, sci-fi, turn-based management RPG. Become the CEO of an R&D behemoth: hire scientists, woo investors, dabble in corporate espionage, and forge the science of tomorrow. Whether the technological wonders that emerge will save humanity—or doom it—is up to you.' FROM games WHERE igdb_id = 388767 ON CONFLICT (game_id, language_code) DO NOTHING;
