INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hag''s Hand', 'A tower defense game that blends Brazilian folklore myths with card management. Protect the forest by summoning the creatures that dwell within the wilds. As invaders push deeper into the untamed woods, the witch Cuca merely watches their movement, waiting for the perfect moment to strike.' FROM games WHERE igdb_id = 388500 ON CONFLICT (game_id, language_code) DO NOTHING;
